# copper_flotation_gen/part8_phase5_alarms.py

def get_phase5_alarms():
    lines = []
    lines.append("(* ==================================================================================================== *)")
    lines.append("(* PHASE 5: ISA-18.2 MULTI-TIER PROCESS ALARMS, ANTI-STICTION DITHER & 32-BIT BIT-PACKED TELEMETRY      *)")
    lines.append("(* Sanding Early Warning, Deadband Clearance Hysteresis, First-Out Root Cause Latch & SCADA Registers   *)")
    lines.append("(* ==================================================================================================== *)")
    lines.append("")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* Step 1: Cell Bottom Sanding Severity Index (SSI) Calculation & Pre-Warning Detection            *)")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* SSI integrates mechanical drive torque, tailings density and feed flow rate dynamics *)")
    lines.append("    rSandingSeverityIndex := (0.45 * (LIMIT(800.0, rAgitatorTorque_Cell1_Nm, 3200.0) - 1200.0) / 1800.0)")
    lines.append("                           + (0.35 * (LIMIT(1.10, rTailings_Density_Voted, 1.65) - 1.25) / 0.35)")
    lines.append("                           - (0.20 * (LIMIT(400.0, rFeed_SlurryFlow_m3h, 1200.0) - 600.0) / 600.0);")
    lines.append("    rSandingSeverityIndex := LIMIT(0.0, rSandingSeverityIndex, 1.0);")
    lines.append("")
    lines.append("    (* First-Order Exponential Lag Filter (Tau = 2.0 s) *)")
    lines.append("    rSandingIndex_Smooth := (0.985 * rSandingIndex_Smooth) + (0.015 * rSandingSeverityIndex);")
    lines.append("    rCalc_SandingSeverityIndex := rSandingIndex_Smooth;")
    lines.append("")
    lines.append("    IF rSandingIndex_Smooth >= 0.65 THEN")
    lines.append("        bSandingPreWarningActive := TRUE;")
    lines.append("    ELSIF rSandingIndex_Smooth <= 0.45 THEN")
    lines.append("        bSandingPreWarningActive := FALSE;")
    lines.append("    END_IF;")
    lines.append("")
    lines.append("    IF rSandingIndex_Smooth >= 0.88 THEN")
    lines.append("        bSandingCriticalTripActive := TRUE;")
    lines.append("    ELSIF rSandingIndex_Smooth <= 0.50 THEN")
    lines.append("        bSandingCriticalTripActive := FALSE;")
    lines.append("    END_IF;")
    lines.append("")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* Step 2: Dart Valve Anti-Stiction Periodic Dither Generator (Breaks Calcium Sulfate Crust)       *)")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    rDitherPhaseRamp := rDitherPhaseRamp + (0.314 * tScanCycleTime_s); (* 0.05 Hz Periodic Cycle *)")
    lines.append("    IF rDitherPhaseRamp >= 6.283185 THEN")
    lines.append("        rDitherPhaseRamp := rDitherPhaseRamp - 6.283185;")
    lines.append("    END_IF;")
    lines.append("    (* Triangular Dither Waveform [-1.5% to +1.5%] *)")
    lines.append("    IF rDitherPhaseRamp < 3.141592 THEN")
    lines.append("        rDitherWaveform_pct := -1.50 + (3.00 * (rDitherPhaseRamp / 3.141592));")
    lines.append("    ELSE")
    lines.append("        rDitherWaveform_pct := 1.50 - (3.00 * ((rDitherPhaseRamp - 3.141592) / 3.141592));")
    lines.append("    END_IF;")
    lines.append("")
    lines.append("    (* Check Inactivity on Each Dart Valve and Inject Dither when Stationary > 30.0 [s] *)")
    lines.append("    FOR mIdx := 0 TO 5 DO")
    lines.append("        IF ABS(vecU_rate[mIdx]) < 0.05 THEN")
    lines.append("            rDartValve_StationaryTime_s[mIdx] := rDartValve_StationaryTime_s[mIdx] + tScanCycleTime_s;")
    lines.append("        ELSE")
    lines.append("            rDartValve_StationaryTime_s[mIdx] := 0.0;")
    lines.append("        END_IF;")
    lines.append("        IF rDartValve_StationaryTime_s[mIdx] >= 30.0 AND (eState >= 3 AND eState <= 10) THEN")
    lines.append("            bDartValve_DitherActive[mIdx] := TRUE;")
    lines.append("        ELSE")
    lines.append("            bDartValve_DitherActive[mIdx] := FALSE;")
    lines.append("        END_IF;")
    lines.append("    END_FOR;")
    lines.append("")
    lines.append("    IF bDartValve_DitherActive[0] THEN rDartValve_Cmd_1_pct := LIMIT(0.0, rDartValve_Cmd_1_pct + rDitherWaveform_pct, 100.0); END_IF;")
    lines.append("    IF bDartValve_DitherActive[1] THEN rDartValve_Cmd_2_pct := LIMIT(0.0, rDartValve_Cmd_2_pct + rDitherWaveform_pct, 100.0); END_IF;")
    lines.append("    IF bDartValve_DitherActive[2] THEN rDartValve_Cmd_3_pct := LIMIT(0.0, rDartValve_Cmd_3_pct + rDitherWaveform_pct, 100.0); END_IF;")
    lines.append("    IF bDartValve_DitherActive[3] THEN rDartValve_Cmd_4_pct := LIMIT(0.0, rDartValve_Cmd_4_pct + rDitherWaveform_pct, 100.0); END_IF;")
    lines.append("    IF bDartValve_DitherActive[4] THEN rDartValve_Cmd_5_pct := LIMIT(0.0, rDartValve_Cmd_5_pct + rDitherWaveform_pct, 100.0); END_IF;")
    lines.append("    IF bDartValve_DitherActive[5] THEN rDartValve_Cmd_6_pct := LIMIT(0.0, rDartValve_Cmd_6_pct + rDitherWaveform_pct, 100.0); END_IF;")
    lines.append("")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* Step 3: ISA-18.2 Multi-Tier Process Alarm Evaluations with Deadband Clearance Hysteresis         *)")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* Cell 1 Pulp Level Alarms *)")
    lines.append("    IF rPulpLevel_Cell1_Voted >= rPulp1_HH_Limit_mm THEN bPulp1_HH_Active := TRUE; ELSIF rPulpLevel_Cell1_Voted <= (rPulp1_HH_Limit_mm - rPulp1_Deadband_mm) THEN bPulp1_HH_Active := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell1_Voted >= rPulp1_H_Limit_mm  THEN bPulp1_H_Active  := TRUE; ELSIF rPulpLevel_Cell1_Voted <= (rPulp1_H_Limit_mm  - rPulp1_Deadband_mm) THEN bPulp1_H_Active  := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell1_Voted <= rPulp1_L_Limit_mm  THEN bPulp1_L_Active  := TRUE; ELSIF rPulpLevel_Cell1_Voted >= (rPulp1_L_Limit_mm  + rPulp1_Deadband_mm) THEN bPulp1_L_Active  := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell1_Voted <= rPulp1_LL_Limit_mm THEN bPulp1_LL_Active := TRUE; ELSIF rPulpLevel_Cell1_Voted >= (rPulp1_LL_Limit_mm + rPulp1_Deadband_mm) THEN bPulp1_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* Cell 6 Pulp Level Alarms *)")
    lines.append("    IF rPulpLevel_Cell6_Voted >= rPulp6_HH_Limit_mm THEN bPulp6_HH_Active := TRUE; ELSIF rPulpLevel_Cell6_Voted <= (rPulp6_HH_Limit_mm - rPulp6_Deadband_mm) THEN bPulp6_HH_Active := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell6_Voted >= rPulp6_H_Limit_mm  THEN bPulp6_H_Active  := TRUE; ELSIF rPulpLevel_Cell6_Voted <= (rPulp6_H_Limit_mm  - rPulp6_Deadband_mm) THEN bPulp6_H_Active  := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell6_Voted <= rPulp6_L_Limit_mm  THEN bPulp6_L_Active  := TRUE; ELSIF rPulpLevel_Cell6_Voted >= (rPulp6_L_Limit_mm  + rPulp6_Deadband_mm) THEN bPulp6_L_Active  := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell6_Voted <= rPulp6_LL_Limit_mm THEN bPulp6_LL_Active := TRUE; ELSIF rPulpLevel_Cell6_Voted >= (rPulp6_LL_Limit_mm + rPulp6_Deadband_mm) THEN bPulp6_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* Cell 12 Pulp Level Alarms *)")
    lines.append("    IF rPulpLevel_Cell12_Voted >= rPulp12_HH_Limit_mm THEN bPulp12_HH_Active := TRUE; ELSIF rPulpLevel_Cell12_Voted <= (rPulp12_HH_Limit_mm - rPulp12_Deadband_mm) THEN bPulp12_HH_Active := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell12_Voted >= rPulp12_H_Limit_mm  THEN bPulp12_H_Active  := TRUE; ELSIF rPulpLevel_Cell12_Voted <= (rPulp12_H_Limit_mm  - rPulp12_Deadband_mm) THEN bPulp12_H_Active  := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell12_Voted <= rPulp12_L_Limit_mm  THEN bPulp12_L_Active  := TRUE; ELSIF rPulpLevel_Cell12_Voted >= (rPulp12_L_Limit_mm  + rPulp12_Deadband_mm) THEN bPulp12_L_Active  := FALSE; END_IF;")
    lines.append("    IF rPulpLevel_Cell12_Voted <= rPulp12_LL_Limit_mm THEN bPulp12_LL_Active := TRUE; ELSIF rPulpLevel_Cell12_Voted >= (rPulp12_LL_Limit_mm + rPulp12_Deadband_mm) THEN bPulp12_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* Froth Bed Thickness Alarms *)")
    lines.append("    IF rFrothHeight_Voted >= rFroth_HH_Limit_mm THEN bFroth_HH_Active := TRUE; ELSIF rFrothHeight_Voted <= (rFroth_HH_Limit_mm - rFroth_Deadband_mm) THEN bFroth_HH_Active := FALSE; END_IF;")
    lines.append("    IF rFrothHeight_Voted >= rFroth_H_Limit_mm  THEN bFroth_H_Active  := TRUE; ELSIF rFrothHeight_Voted <= (rFroth_H_Limit_mm  - rFroth_Deadband_mm) THEN bFroth_H_Active  := FALSE; END_IF;")
    lines.append("    IF rFrothHeight_Voted <= rFroth_L_Limit_mm  THEN bFroth_L_Active  := TRUE; ELSIF rFrothHeight_Voted >= (rFroth_L_Limit_mm  + rFroth_Deadband_mm) THEN bFroth_L_Active  := FALSE; END_IF;")
    lines.append("    IF rFrothHeight_Voted <= rFroth_LL_Limit_mm THEN bFroth_LL_Active := TRUE; ELSIF rFrothHeight_Voted >= (rFroth_LL_Limit_mm + rFroth_Deadband_mm) THEN bFroth_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* Aeration Manifold Air Pressure Alarms *)")
    lines.append("    IF rAirPress_Manifold_Voted >= rAirPress_HH_Limit_kPa THEN bAirPress_HH_Active := TRUE; ELSIF rAirPress_Manifold_Voted <= (rAirPress_HH_Limit_kPa - rAirPress_Deadband_kPa) THEN bAirPress_HH_Active := FALSE; END_IF;")
    lines.append("    IF rAirPress_Manifold_Voted >= rAirPress_H_Limit_kPa  THEN bAirPress_H_Active  := TRUE; ELSIF rAirPress_Manifold_Voted <= (rAirPress_H_Limit_kPa  - rAirPress_Deadband_kPa) THEN bAirPress_H_Active  := FALSE; END_IF;")
    lines.append("    IF rAirPress_Manifold_Voted <= rAirPress_L_Limit_kPa  THEN bAirPress_L_Active  := TRUE; ELSIF rAirPress_Manifold_Voted >= (rAirPress_L_Limit_kPa  + rAirPress_Deadband_kPa) THEN bAirPress_L_Active  := FALSE; END_IF;")
    lines.append("    IF rAirPress_Manifold_Voted <= rAirPress_LL_Limit_kPa THEN bAirPress_LL_Active := TRUE; ELSIF rAirPress_Manifold_Voted >= (rAirPress_LL_Limit_kPa + rAirPress_Deadband_kPa) THEN bAirPress_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* Concentrate Copper Grade Alarms *)")
    lines.append("    IF rXRF_ConcCu_Voted >= rXRF_ConcCu_HH_Limit_pct THEN bXRF_ConcCu_HH_Active := TRUE; ELSIF rXRF_ConcCu_Voted <= (rXRF_ConcCu_HH_Limit_pct - rXRF_ConcCu_Deadband_pct) THEN bXRF_ConcCu_HH_Active := FALSE; END_IF;")
    lines.append("    IF rXRF_ConcCu_Voted >= rXRF_ConcCu_H_Limit_pct  THEN bXRF_ConcCu_H_Active  := TRUE; ELSIF rXRF_ConcCu_Voted <= (rXRF_ConcCu_H_Limit_pct  - rXRF_ConcCu_Deadband_pct) THEN bXRF_ConcCu_H_Active  := FALSE; END_IF;")
    lines.append("    IF rXRF_ConcCu_Voted <= rXRF_ConcCu_L_Limit_pct  THEN bXRF_ConcCu_L_Active  := TRUE; ELSIF rXRF_ConcCu_Voted >= (rXRF_ConcCu_L_Limit_pct  + rXRF_ConcCu_Deadband_pct) THEN bXRF_ConcCu_L_Active  := FALSE; END_IF;")
    lines.append("    IF rXRF_ConcCu_Voted <= rXRF_ConcCu_LL_Limit_pct THEN bXRF_ConcCu_LL_Active := TRUE; ELSIF rXRF_ConcCu_Voted >= (rXRF_ConcCu_LL_Limit_pct + rXRF_ConcCu_Deadband_pct) THEN bXRF_ConcCu_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* Scavenger Tailings Slurry Density Alarms *)")
    lines.append("    IF rTailings_Density_Voted >= rTailDensity_HH_Limit_gcc THEN bTailDensity_HH_Active := TRUE; ELSIF rTailings_Density_Voted <= (rTailDensity_HH_Limit_gcc - rTailDensity_Deadband_gcc) THEN bTailDensity_HH_Active := FALSE; END_IF;")
    lines.append("    IF rTailings_Density_Voted >= rTailDensity_H_Limit_gcc  THEN bTailDensity_H_Active  := TRUE; ELSIF rTailings_Density_Voted <= (rTailDensity_H_Limit_gcc  - rTailDensity_Deadband_gcc) THEN bTailDensity_H_Active  := FALSE; END_IF;")
    lines.append("    IF rTailings_Density_Voted <= rTailDensity_L_Limit_gcc  THEN bTailDensity_L_Active  := TRUE; ELSIF rTailings_Density_Voted >= (rTailDensity_L_Limit_gcc  + rTailDensity_Deadband_gcc) THEN bTailDensity_L_Active  := FALSE; END_IF;")
    lines.append("    IF rTailings_Density_Voted <= rTailDensity_LL_Limit_gcc THEN bTailDensity_LL_Active := TRUE; ELSIF rTailings_Density_Voted >= (rTailDensity_LL_Limit_gcc + rTailDensity_Deadband_gcc) THEN bTailDensity_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* Agitator Drive Torque Alarms *)")
    lines.append("    IF rAgitatorTorque_Cell1_Nm >= rAgitatorTorque_HH_Limit_Nm THEN bAgitatorTorque_HH_Active := TRUE; ELSIF rAgitatorTorque_Cell1_Nm <= (rAgitatorTorque_HH_Limit_Nm - rAgitatorTorque_Deadband_Nm) THEN bAgitatorTorque_HH_Active := FALSE; END_IF;")
    lines.append("    IF rAgitatorTorque_Cell1_Nm >= rAgitatorTorque_H_Limit_Nm  THEN bAgitatorTorque_H_Active  := TRUE; ELSIF rAgitatorTorque_Cell1_Nm <= (rAgitatorTorque_H_Limit_Nm  - rAgitatorTorque_Deadband_Nm) THEN bAgitatorTorque_H_Active  := FALSE; END_IF;")
    lines.append("    IF rAgitatorTorque_Cell1_Nm <= rAgitatorTorque_L_Limit_Nm  THEN bAgitatorTorque_L_Active  := TRUE; ELSIF rAgitatorTorque_Cell1_Nm >= (rAgitatorTorque_L_Limit_Nm  + rAgitatorTorque_Deadband_Nm) THEN bAgitatorTorque_L_Active  := FALSE; END_IF;")
    lines.append("    IF rAgitatorTorque_Cell1_Nm <= rAgitatorTorque_LL_Limit_Nm THEN bAgitatorTorque_LL_Active := TRUE; ELSIF rAgitatorTorque_Cell1_Nm >= (rAgitatorTorque_LL_Limit_Nm + rAgitatorTorque_Deadband_Nm) THEN bAgitatorTorque_LL_Active := FALSE; END_IF;")
    lines.append("")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* Step 4: First-Out Critical Alarm Capture Latching Logic                                          *)")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    IF NOT bFirstOutLatched THEN")
    lines.append("        IF bEmergencyStop THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000001; bFirstOutLatched := TRUE;")
    lines.append("        ELSIF bPulp1_HH_Active THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000002; bFirstOutLatched := TRUE;")
    lines.append("        ELSIF bPulp1_LL_Active THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000003; bFirstOutLatched := TRUE;")
    lines.append("        ELSIF bPulp12_HH_Active THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000004; bFirstOutLatched := TRUE;")
    lines.append("        ELSIF bAirPress_LL_Active THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000005; bFirstOutLatched := TRUE;")
    lines.append("        ELSIF bAgitatorTorque_HH_Active THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000006; bFirstOutLatched := TRUE;")
    lines.append("        ELSIF bSandingCriticalTripActive THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000007; bFirstOutLatched := TRUE;")
    lines.append("        ELSIF bPulpLevel_Cell1_Trip OR bAirPress_Trip THEN")
    lines.append("            dwFirstOutCapturedCode := 16#00000008; bFirstOutLatched := TRUE;")
    lines.append("        END_IF;")
    lines.append("    ELSIF bFaultReset AND bAlarmAck THEN")
    lines.append("        bFirstOutLatched := FALSE;")
    lines.append("        dwFirstOutCapturedCode := 16#00000000;")
    lines.append("    END_IF;")
    lines.append("    dwFirstOutWord := dwFirstOutCapturedCode;")
    lines.append("")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* Step 5: Bit-Packed Telemetry DWORD Assembly                                                      *)")
    lines.append("    (* ------------------------------------------------------------------------------------------------ *)")
    lines.append("    (* Assemble dwStatusWord1: Plant & Subsystem Operational State Bits *)")
    lines.append("    dwStatusWord1 := 16#00000000;")
    lines.append("    dwStatusWord1 := dwStatusWord1 OR INT_TO_DWORD(eState AND 16#000F);")
    lines.append("    IF bEnable THEN dwStatusWord1 := dwStatusWord1 OR 16#00000010; END_IF;")
    lines.append("    IF bAutoCycleStart THEN dwStatusWord1 := dwStatusWord1 OR 16#00000020; END_IF;")
    lines.append("    IF eState = 6 THEN dwStatusWord1 := dwStatusWord1 OR 16#00000040; END_IF;")
    lines.append("    IF bFrothWashWaterActive THEN dwStatusWord1 := dwStatusWord1 OR 16#00000080; END_IF;")
    lines.append("    IF bAirPurgeNonReturnValveOpen THEN dwStatusWord1 := dwStatusWord1 OR 16#00000100; END_IF;")
    lines.append("    IF bFrothCrowderPaddleMotorRun THEN dwStatusWord1 := dwStatusWord1 OR 16#00000200; END_IF;")
    lines.append("    IF bSanderUpBottomFlushSolenoid THEN dwStatusWord1 := dwStatusWord1 OR 16#00000400; END_IF;")
    lines.append("    IF bTailingsEmergencyDumpValve THEN dwStatusWord1 := dwStatusWord1 OR 16#00000800; END_IF;")
    lines.append("    IF bFeedDivertToTailingsDam THEN dwStatusWord1 := dwStatusWord1 OR 16#00001000; END_IF;")
    lines.append("    IF bDartValve_DitherActive[0] OR bDartValve_DitherActive[1] THEN dwStatusWord1 := dwStatusWord1 OR 16#00002000; END_IF;")
    lines.append("    IF eState = 10 THEN dwStatusWord1 := dwStatusWord1 OR 16#00004000; END_IF;")
    lines.append("    IF bAirBlowerReady THEN dwStatusWord1 := dwStatusWord1 OR 16#00008000; END_IF;")
    lines.append("    IF bTailingsGateOpenFeedback THEN dwStatusWord1 := dwStatusWord1 OR 16#00010000; END_IF;")
    lines.append("    IF bThickenerReadyFeedback THEN dwStatusWord1 := dwStatusWord1 OR 16#00020000; END_IF;")
    lines.append("")
    lines.append("    (* Assemble dwStatusWord2: 2oo3 TMR Health, Degraded Modes & Observer Convergence *)")
    lines.append("    dwStatusWord2 := 16#00000000;")
    lines.append("    IF bPulpLevel_Cell1_HealthA AND bPulpLevel_Cell1_HealthB AND bPulpLevel_Cell1_HealthC THEN dwStatusWord2 := dwStatusWord2 OR 16#00000001; END_IF;")
    lines.append("    IF bPulpLevel_Cell1_Degraded THEN dwStatusWord2 := dwStatusWord2 OR 16#00000002; END_IF;")
    lines.append("    IF bPulpLevel_Cell6_HealthA AND bPulpLevel_Cell6_HealthB AND bPulpLevel_Cell6_HealthC THEN dwStatusWord2 := dwStatusWord2 OR 16#00000004; END_IF;")
    lines.append("    IF bPulpLevel_Cell6_Degraded THEN dwStatusWord2 := dwStatusWord2 OR 16#00000008; END_IF;")
    lines.append("    IF bPulpLevel_Cell12_HealthA AND bPulpLevel_Cell12_HealthB AND bPulpLevel_Cell12_HealthC THEN dwStatusWord2 := dwStatusWord2 OR 16#00000010; END_IF;")
    lines.append("    IF bPulpLevel_Cell12_Degraded THEN dwStatusWord2 := dwStatusWord2 OR 16#00000020; END_IF;")
    lines.append("    IF bFrothHeight_HealthA AND bFrothHeight_HealthB AND bFrothHeight_HealthC THEN dwStatusWord2 := dwStatusWord2 OR 16#00000040; END_IF;")
    lines.append("    IF bFrothHeight_Degraded THEN dwStatusWord2 := dwStatusWord2 OR 16#00000080; END_IF;")
    lines.append("    IF bAirPress_HealthA AND bAirPress_HealthB AND bAirPress_HealthC THEN dwStatusWord2 := dwStatusWord2 OR 16#00000100; END_IF;")
    lines.append("    IF bAirPress_Degraded THEN dwStatusWord2 := dwStatusWord2 OR 16#00000200; END_IF;")
    lines.append("    IF bXRF_ConcCu_HealthA AND bXRF_ConcCu_HealthB AND bXRF_ConcCu_HealthC THEN dwStatusWord2 := dwStatusWord2 OR 16#00000400; END_IF;")
    lines.append("    IF bXRF_ConcCu_Degraded THEN dwStatusWord2 := dwStatusWord2 OR 16#00000800; END_IF;")
    lines.append("    IF bTailings_Density_HealthA AND bTailings_Density_HealthB AND bTailings_Density_HealthC THEN dwStatusWord2 := dwStatusWord2 OR 16#00001000; END_IF;")
    lines.append("    IF bTailings_Density_Degraded THEN dwStatusWord2 := dwStatusWord2 OR 16#00002000; END_IF;")
    lines.append("    IF ABS(vecInnov[0]) < 15.0 AND ABS(vecInnov[3]) < 10.0 THEN dwStatusWord2 := dwStatusWord2 OR 16#00004000; END_IF;")
    lines.append("    IF rBubbleSurfaceAreaFlux_Sb_s >= 50.0 THEN dwStatusWord2 := dwStatusWord2 OR 16#00008000; END_IF;")
    lines.append("    IF rFrothRecoveryFactor_Alpha >= 0.60 THEN dwStatusWord2 := dwStatusWord2 OR 16#00010000; END_IF;")
    lines.append("")
    lines.append("    (* Assemble dwAlarmWord1: ISA-18.2 Critical Trips & Interlocks (HH/LL) *)")
    lines.append("    dwAlarmWord1 := 16#00000000;")
    lines.append("    IF bEmergencyStop THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000001; END_IF;")
    lines.append("    IF bPulp1_HH_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000002; END_IF;")
    lines.append("    IF bPulp1_LL_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000004; END_IF;")
    lines.append("    IF bPulp6_HH_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000008; END_IF;")
    lines.append("    IF bPulp6_LL_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000010; END_IF;")
    lines.append("    IF bPulp12_HH_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000020; END_IF;")
    lines.append("    IF bPulp12_LL_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000040; END_IF;")
    lines.append("    IF bFroth_HH_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000080; END_IF;")
    lines.append("    IF bFroth_LL_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000100; END_IF;")
    lines.append("    IF bAirPress_HH_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000200; END_IF;")
    lines.append("    IF bAirPress_LL_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000400; END_IF;")
    lines.append("    IF bTailDensity_HH_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00000800; END_IF;")
    lines.append("    IF bTailDensity_LL_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00001000; END_IF;")
    lines.append("    IF bAgitatorTorque_HH_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00002000; END_IF;")
    lines.append("    IF bAgitatorTorque_LL_Active THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00004000; END_IF;")
    lines.append("    IF bSandingCriticalTripActive THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00008000; END_IF;")
    lines.append("    IF bPulpLevel_Cell1_Trip OR bPulpLevel_Cell6_Trip OR bPulpLevel_Cell12_Trip THEN dwAlarmWord1 := dwAlarmWord1 OR 16#00010000; END_IF;")
    lines.append("")
    lines.append("    (* Assemble dwAlarmWord2: ISA-18.2 Process Warning Deviations (H/L) *)")
    lines.append("    dwAlarmWord2 := 16#00000000;")
    lines.append("    IF bPulp1_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000001; END_IF;")
    lines.append("    IF bPulp1_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000002; END_IF;")
    lines.append("    IF bPulp6_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000004; END_IF;")
    lines.append("    IF bPulp6_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000008; END_IF;")
    lines.append("    IF bPulp12_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000010; END_IF;")
    lines.append("    IF bPulp12_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000020; END_IF;")
    lines.append("    IF bFroth_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000040; END_IF;")
    lines.append("    IF bFroth_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000080; END_IF;")
    lines.append("    IF bAirPress_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000100; END_IF;")
    lines.append("    IF bAirPress_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000200; END_IF;")
    lines.append("    IF bXRF_ConcCu_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000400; END_IF;")
    lines.append("    IF bXRF_ConcCu_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00000800; END_IF;")
    lines.append("    IF bTailDensity_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00001000; END_IF;")
    lines.append("    IF bTailDensity_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00002000; END_IF;")
    lines.append("    IF bAgitatorTorque_H_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00004000; END_IF;")
    lines.append("    IF bAgitatorTorque_L_Active THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00008000; END_IF;")
    lines.append("    IF bSandingPreWarningActive THEN dwAlarmWord2 := dwAlarmWord2 OR 16#00010000; END_IF;")
    lines.append("")
    lines.append("    (* Increment Rolling Cycle Execution Counter *)")
    lines.append("    iCycleCounter := iCycleCounter + 1;")
    lines.append("")
    lines.append("END_FUNCTION_BLOCK")

    return "\n".join(lines)
